export type BidplaceLogoMotion =
  | 'static'
  | 'intro'
  | 'loading'
  | 'error'
  | 'glance';

export const BIDPLACE_PAGE_LOGO_SIZE = 104;
export const BIDPLACE_LOGO_BOUNCE_MS = 900;
export const BIDPLACE_LOGO_BOUNCE_LIFT_PX = 16;
export const BIDPLACE_LOGO_BLINK_MS = 520;

const glanceDeltaX =
  bidplaceLogoMark.pupils.glance.left.cx -
  bidplaceLogoMark.pupils.default.left.cx;
const glanceDeltaY =
  bidplaceLogoMark.pupils.glance.left.cy -
  bidplaceLogoMark.pupils.default.left.cy;

export const bidplaceLogoGlanceTranslate = {
  x: `${(glanceDeltaX / bidplaceLogoMark.viewBox.width) * 100}%`,
  y: `${(glanceDeltaY / bidplaceLogoMark.viewBox.height) * 100}%`,
} as const;

export function bidplaceLogoMotionActive(
  motion: BidplaceLogoMotion,
  reducedMotion: boolean,
) {
  return (
    !reducedMotion &&
    (motion === 'intro' ||
      motion === 'loading' ||
      motion === 'error' ||
      motion === 'glance')
  );
}
